        }
      &gt;
        Apply your loyalty discount
      &lt;/s-button&gt;
    );
  } else {
    return (
      &lt;s-banner tone="warning"&gt;
        Loyalty discounts are unavailable
      &lt;/s-banner&gt;
    );
  }
}

