import '@shopify/ui-extensions/preact';
import {render} from 'preact';

import {useDeliveryGroup} from '@shopify/ui-extensions/checkout/preact';

export default function extension() {
  render(&lt;Extension /&gt;, document.body);
}

function Extension() {
  const firstDeliveryGroup = useDeliveryGroup(
    shopify.deliveryGroups.value[0],
  );

  if (!firstDeliveryGroup) {
    return null;
  }

  const selectedDeliveryOption =
    firstDeliveryGroup?.selectedDeliveryOption;

  return (
    &lt;s-banner&gt;
      Selected delivery option:{' '}
      {selectedDeliveryOption?.title}
    &lt;/s-banner&gt;
  );
}

import '@shopify/ui-extensions/preact';
import {render} from 'preact';

import {useShippingOptionTarget} from '@shopify/ui-extensions/checkout/preact';

export default function extension() {
  render(&lt;Extension /&gt;, document.body);
}

function Extension() {
  const {shippingOptionTarget, isTargetSelected} =
    useShippingOptionTarget();
  const title = shippingOptionTarget.title;

  return (
    &lt;s-text&gt;
      Shipping method: {title} is{' '}
      {isTargetSelected ? '' : 'not'} selected.
    &lt;/s-text&gt;
  );
}

import '@shopify/ui-extensions/preact';
import {render} from 'preact';

import {usePickupLocationOptionTarget} from '@shopify/ui-extensions/checkout/preact';

export default function extension() {
  render(&lt;Extension /&gt;, document.body);
}

function Extension() {
  const {
    isTargetSelected,
    pickupLocationOptionTarget,
  } = usePickupLocationOptionTarget();

  const title = pickupLocationOptionTarget?.title;

  if (isTargetSelected) {
    return &lt;s-text&gt;{title}&lt;/s-text&gt;;
