function Extension() {
  const {query} = shopify;
  const [data, setData] = useState();

  useEffect(() =&gt; {
    shopify
      .query(
        `query ($first: Int!) {
        products(first: $first) {
          nodes {
            id
            title
          }
        }
      }`,
        {
          variables: {first: 5},
        },
      )
      .then(({data, errors}) =&gt; setData(data))
      .catch(console.error);
  }, [query]);

  return (
    &lt;s-unordered-list&gt;
      {data?.products?.nodes.map((node) =&gt; (
        &lt;s-list-item key={node.id}&gt;
          {node.title}
        &lt;/s-list-item&gt;
      ))}
    &lt;/s-unordered-list&gt;
  );
}

