import '@shopify/ui-extensions/preact';
import {render} from 'preact';

export default function extension() {
  render(&lt;Extension /&gt;, document.body);
}

function Extension() {
  // As of version 2025-10, you no longer need the `useSubscription` hook.
  // When you access `.value` on subscribable properties,
  // Preact will automatically re-render as `.value` changes.
  return (
    &lt;s-banner&gt;
      {shopify.cost.totalAmount.value.amount}
    &lt;/s-banner&gt;
  );
}

export default async function extension() {
  // 1. Use the suggestion the buyer selected
  const {selectedSuggestion} = shopify.target;

  // 2. Fetch the address parts to format the address
  const response = await fetch(
    `https://your-app.com/api/fetch-address?id=${selectedSuggestion.id}`,
  );
  const {
    address1,
    address2,
    city,
    zip,
    provinceCode,
    countryCode,
  } = await response.json();

  // 3. Return a formatted address
  return {
    formattedAddress: {
      address1,
      address2,
      city,
      zip,
      provinceCode,
      countryCode,
    },
  };
}

